// شرعاء V2 — صياغات يفهمها العميل بعفوية ولا يلتقطها مستخرج المتطلبات الحالي (requirements.mjs لا يُعدَّل):
//  (1) أفعال الأمر: «أبعد الماستر عن الدرج» (كانت تسقط بصمت: لا قاعدة ولا «لم أفهم»)، «قرّب المطبخ من الطعام»، «انقل المطبخ للخلف».
//  (2) طلبات تخالف اشتراطًا نظاميًا متحققًا: نسبة بناء فوق 75٪، أو ارتداد دون الحد (تُعاد قيمًا لا تُنفَّذ).
// كلها قواعد نصية حتمية؛ ما لا يُفهم يُعاد في unclear ولا يُهمل.
import { normalizeAr } from '../requirements.mjs';

const AR = '\\u0600-\\u06FF';
const W = `[${AR}a-z0-9]`;
const verbs = [
  { re: new RegExp(`(?<![${AR}])(?:ابعد|ابعدي|ابعدو|بعد)\\s+(.{2,40}?)\\s+(?:عن|من)\\s+`, 'g'), to: (subj) => `${subj} بعيده عن ` },
  { re: new RegExp(`(?<![${AR}])(?:قرب|قربي|قربو)\\s+(.{2,40}?)\\s+(?:من|ل|الى)\\s+`, 'g'), to: (subj) => `${subj} قريب من ` },
  { re: new RegExp(`(?<![${AR}])(?:الصق|ألصق|الصقي|الصقو)\\s+(.{2,40}?)\\s+(?:ب|مع|في)\\s*`, 'g'), to: (subj) => `${subj} جنب ` },
  { re: new RegExp(`(?<![${AR}])(?:انقل|نقل|حرك|حط|حطي|ضع)\\s+(.{2,40}?)\\s+(?:لل|(?:ل|الي|في|ع|علي)\\s*(?:ال)?)(خلف|ورا|وراء|امام|قدام|شارع)(?![${AR}])`, 'g'), to: (subj, where) => `${subj} ${/خلف|ورا|وراء/.test(where) ? 'في الخلف' : /شارع/.test(where) ? 'على الشارع' : 'في الامام'}` },
];
/** يعيد النص بعد تحويل أفعال الأمر إلى جمل وصفية يفهمها المستخرج، ومعه ما حُوِّل (للشفافية). */
export function normalizeImperatives(text) {
  let t = normalizeAr(text); const changed = [];
  for (const v of verbs) t = t.replace(v.re, (m, subj, where) => { const out = v.to(subj.trim(), where); changed.push({ from: m.trim(), to: out.trim() }); return out; });
  return { text: t, changed };
}

// ------------------------------------------------------------------------------------------ طلبات تخالف اللائحة
/**
 * يستخرج من الكلام طلبًا صريحًا يمسّ حدًا نظاميًا: نسبة البناء (٪ من الأرض) أو ارتداد بالمتر (للجار أو للشارع).
 * يعيد { coveragePct?, setback?: { side:'neighbour'|'front', m }, quote }. لا يحكم هنا بالمخالفة؛ الحكم في brief.deriveConflicts من regulations-sa.
 */
export function extractRegulatoryAsks(text) {
  const t = normalizeAr(text), out = {};
  const cov = t.match(/(?:نسبه ال)?(?:بناء|تغطيه|مسطح)[^،,.؛]{0,18}?(\d{2,3}(?:\.\d+)?) ?(?:%|٪|بالمئه|بالميه|في المئه)/) || t.match(/(\d{2,3}(?:\.\d+)?) ?(?:%|٪|بالمئه|بالميه)[^،,.؛]{0,14}(?:بناء|من ال?ارض|تغطيه)/);
  if (cov) { const n = Number(cov[1]); if (n > 0 && n <= 100) { out.coveragePct = n; out.quote = cov[0].trim(); } }
  else if (/(?:بناء|ابني|نبني|ابغي ابني)[^،,.؛]{0,12}(?:على )?(?:كامل|كل|جميع) ال?ارض|(?:كامل|كل) مساحه ال?ارض/.test(t)) { out.coveragePct = 100; out.quote = (t.match(/(?:بناء|ابني|نبني|ابغي ابني)[^،,.؛]{0,12}(?:على )?(?:كامل|كل|جميع) ال?ارض|(?:كامل|كل) مساحه ال?ارض/) || [''])[0].trim(); }
  const none = t.match(/(?:بدون|من غير|بلا|لا) ارتداد(?:ات)?(?: (?:من|عن|مع))?(?: ال?(?:جار|جيران|جانبي|امامي|شارع))?/) || t.match(/(?:الصق|لاصق|ملاصق)(?:ه|ين)? (?:ب|ل)?ال?جار/) || t.match(/(?:على|عند) حد(?:ود)? ال?جار/);
  const num = t.match(/ارتداد(?:ات)?(?: ال?(?:جار|جيران|جانبي|جانب|امامي|اماميه|شارع|واجهه))? ?(?:يكون|بس|فقط|مترين|متر)? ?(\d+(?:\.\d+)?|مترين) ?(?:م|متر)?/);
  if (none || num) {
    const raw = (none || num)[0], m = none ? 0 : (num[1] === 'مترين' ? 2 : Number(num[1]));
    const front = /(امامي|اماميه|شارع|واجهه)/.test(raw) && !/جار|جيران|جانب/.test(raw), nb = /جار|جيران|جانب/.test(raw);
    out.setback = { side: front ? 'front' : nb ? 'neighbour' : 'any', m }; out.quote = out.quote || raw.trim();
  }
  return out;
}
